fixtures.src/styles/animations.css:
@keyframes smoothSlideFadeIn {
  0% {
    opacity: 0;
    transform: translate3d(0, 24px, 0) scale(0.96);
  }
  100% {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
  }
}

@keyframes scrollProgressScale {
  from {
    transform: scaleX(0);
  }
  to {
    transform: scaleX(1);
  }
}

.scroll-progress-bar {
  transform-origin: left center;
  animation: scrollProgressScale auto linear;
  animation-timeline: scroll(root);
}

.reveal-on-scroll {
  animation: smoothSlideFadeIn auto ease-out both;
  animation-timeline: view();
  animation-range: entry 10% cover 30%;
}

.popover-card {
  opacity: 1;
  transform: scale(1);
  transition: opacity 0.3s ease, transform 0.3s ease, overlay 0.3s ease allow-discrete, display 0.3s ease allow-discrete;
}

@starting-style {
  .popover-card {
    opacity: 0;
    transform: scale(0.92);
  }
}

@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

